"""Self-contained, offline viewer for recorded simulator frames."""
import json
from html import escape

def write_replay(path,frames,policy="greedy",seed=0):
    data=json.dumps({'size':16,'maxHunger':20,'frames':frames}).replace('<',r'\u003c').replace('>',r'\u003e').replace('&',r'\u0026').replace(chr(0x2028),r'\u2028').replace(chr(0x2029),r'\u2029')
    html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Survival pilot replay</title>
<style>body{margin:24px auto;max-width:680px;padding:0 16px;background:#14191d;color:#edf2f5;font:16px system-ui}canvas{width:100%;max-width:512px;image-rendering:pixelated;border:1px solid #64717c}input{width:100%}button{padding:8px 16px}small{display:block;line-height:1.6}</style>
<h1>Survival pilot · recorded replay</h1><p>BASELINE_LABEL. This is an actual simulator trace, not a learned agent or research result.</p><canvas id="world" width="512" height="512" aria-label="Recorded 16 by 16 world, food shown green and agents numbered">Replay requires JavaScript.</canvas><p id="status" aria-live="polite"></p><button id="play">Play</button><label>Recorded timestep <input id="tick" type="range" min="0" value="0"></label><small>Green squares: food. Numbered colored squares: living agents. Bar: remaining hunger. This viewer shows the full world for inspection; policies receive only local observations. No external requests or services.</small>
<script>const data=DATA;const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),slider=document.getElementById('tick'),button=document.getElementById('play');slider.max=data.frames.length-1;let timer=null;function draw(){const f=data.frames[Number(slider.value)],s=canvas.width/data.size;ctx.fillStyle='#202a31';ctx.fillRect(0,0,512,512);ctx.strokeStyle='#34424c';for(let i=0;i<=data.size;i++){ctx.beginPath();ctx.moveTo(i*s,0);ctx.lineTo(i*s,512);ctx.moveTo(0,i*s);ctx.lineTo(512,i*s);ctx.stroke()}ctx.fillStyle='#65c78f';for(const[y,x]of f.food)ctx.fillRect(x*s+10,y*s+10,12,12);f.positions.forEach(([y,x],i)=>{if(!f.alive[i])return;ctx.fillStyle=`hsl(${i*45},70%,65%)`;ctx.fillRect(x*s+2,y*s+2,s-4,s-4);ctx.fillStyle='#10151a';ctx.font='bold 15px system-ui';ctx.fillText(String(i),x*s+10,y*s+21);ctx.fillStyle='#fff';ctx.fillRect(x*s+3,y*s+s-5,(s-6)*f.hunger[i]/data.maxHunger,3)});document.getElementById('status').textContent=`Step ${f.tick} · ${f.alive.filter(Boolean).length}/8 alive · ${f.food.length} food`;}slider.oninput=draw;button.onclick=()=>{if(timer){clearInterval(timer);timer=null;button.textContent='Play';return}if(Number(slider.value)>=data.frames.length-1)slider.value=0;button.textContent='Pause';timer=setInterval(()=>{if(Number(slider.value)>=data.frames.length-1){clearInterval(timer);timer=null;button.textContent='Play';return}slider.value=Number(slider.value)+1;draw()},150)};draw();</script></html>'''
    label = f'Observation-limited {policy} baseline, seed {seed}'
    path.write_text(html.replace('DATA',data).replace('BASELINE_LABEL',escape(label)))
